import{_ as t,o as a,c as o,a6 as s}from"./chunks/framework.DIp0zHSV.js";const p=JSON.parse('{"title":"Installation","description":"Install LCARdS from the Home Assistant Marketplace (HACS), add the integration (Home Assistant 2026.11 or newer) and set it up from the LCARdS Config panel.","frontmatter":{"description":"Install LCARdS from the Home Assistant Marketplace (HACS), add the integration (Home Assistant 2026.11 or newer) and set it up from the LCARdS Config panel."},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1794184759000}'),n={name:"getting-started/installation.md"};function r(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p><strong>Install LCARdS from the Home Assistant Marketplace, add the LCARdS integration, then create its helpers in the LCARdS Config panel.</strong> There is nothing else to install: the integration loads the cards on every dashboard.</p><ul><li><strong>Needs Home Assistant 2026.11 or newer.</strong> LCARdS relies on 2026.11&#39;s chip styling and dashboard card paths, and on 2026.10&#39;s dashboard visibility handling and validation library. The Marketplace doesn&#39;t offer it to older versions, and on an older version the integration logs an error and does not load.</li><li>Something not working after installing? See <a href="./getting-help.html">Getting Help</a>. The LCARdS Config panel&#39;s <strong>Welcome</strong> tab also has a health check for common installation problems.</li></ul><div class="tip custom-block"><p class="custom-block-title">Pair it with HA-LCARS</p><p>LCARdS is designed to pair with the <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS themes</a>. HA-LCARS includes LCARdS theme profiles (<strong>LCARS Picard [LCARdS Red Accent]</strong> and <strong>[LCARdS Blue Accent]</strong>): choose one as your Home Assistant theme and Home Assistant&#39;s own screens match your LCARdS cards. See <a href="./../configuration/ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>.</p></div><h2 id="_1-install-from-the-home-assistant-marketplace-hacs" tabindex="-1">1. Install from the Home Assistant Marketplace (HACS) <a class="header-anchor" href="#_1-install-from-the-home-assistant-marketplace-hacs" aria-label="Permalink to &quot;1. Install from the Home Assistant Marketplace (HACS)&quot;">​</a></h2><p><strong>Download LCARdS as a Marketplace integration, then restart Home Assistant.</strong></p><p><a href="https://my.home-assistant.io/redirect/marketplace_repository/?owner=snootched&amp;repository=lcards&amp;category=integrations" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/marketplace_repository.svg" alt="Open your Home Assistant instance and open a repository in the Marketplace."></a></p><ol><li>Open <strong>Marketplace</strong> in Home Assistant.</li><li>Go to <strong>Integrations</strong> and search for <strong>LCARdS</strong>.</li><li>Click <strong>Download</strong> and confirm.</li><li><strong>Restart Home Assistant</strong>, then <a href="#_2-add-the-integration">add the integration</a>.</li></ol><details class="details custom-block"><summary>Manual installation (unmanaged updates)</summary><ol><li>Download <code>lcards.zip</code> from the <a href="https://github.com/snootched/lcards/releases/latest" target="_blank" rel="noreferrer">latest GitHub release</a>.</li><li>Extract the contents into <code>config/custom_components/lcards/</code>. The folder should hold <code>manifest.json</code> and <code>__init__.py</code> directly, not a nested <code>lcards/lcards/</code> folder.</li><li><strong>Restart Home Assistant</strong>, then <a href="#_2-add-the-integration">add the integration</a>.</li></ol><p>Updates don&#39;t arrive by themselves this way: repeat these steps for each release.</p></details><h2 id="_2-add-the-integration" tabindex="-1">2. Add the integration <a class="header-anchor" href="#_2-add-the-integration" aria-label="Permalink to &quot;2. Add the integration&quot;">​</a></h2><p><strong>Go to Settings &gt; Devices &amp; services &gt; Add integration and pick LCARdS.</strong> It asks no questions, and only one LCARdS entry can be added.</p><ul><li>The integration connects Home Assistant to the LCARdS cards, and adds the <strong>LCARdS Config</strong> panel to the sidebar.</li><li>Its options are listed under <a href="#integration-options">Integration options</a>.</li></ul><h2 id="_3-first-setup" tabindex="-1">3. First setup <a class="header-anchor" href="#_3-first-setup" aria-label="Permalink to &quot;3. First setup&quot;">​</a></h2><p><strong>Choose a theme, then create the helpers in the LCARdS Config panel.</strong> The panel&#39;s <strong>Welcome</strong> tab walks you through the same steps.</p><ol><li><strong>Choose your HA-LCARS theme</strong> (recommended), ideally one of the LCARdS profiles HA-LCARS includes. See <a href="./../configuration/ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>.</li><li><strong>Create the helpers.</strong> Open <strong>LCARdS Config</strong> in the sidebar, go to the <strong>Helpers</strong> tab and click <strong>Create All</strong>. LCARdS keeps alert mode, sound and sizing settings in Home Assistant helpers, and several features (alert mode, the alert overlay, sounds) need them.</li><li><strong>Optional: customize your alert colours.</strong> The <strong>Alert Mode Lab</strong> in <strong>Theme Studio</strong> sets how each alert mode recolours your dashboards. See <a href="./../configuration/alert-mode-lab.html">Alert Mode Lab</a>.</li><li><strong>Optional: set up sounds.</strong> The <strong>Sounds</strong> tab turns sounds on and picks a sound scheme you can customize. See <a href="./../configuration/sounds.html">Sound Configuration</a>.</li><li><strong>Check the setup.</strong> <strong>Welcome &gt; Support &amp; system info</strong> runs a health check (versions, browser cache, card-mod leftovers).</li></ol><p>The <a href="./../configuration/">Configuration</a> section covers every panel tab in detail.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./building-dashboards.html">Build a dashboard</a></strong>: pick cards and lay out your first LCARS screen.</li><li><strong><a href="./dashboard-gallery.html">Browse the gallery</a></strong>: start from a complete dashboard.</li><li>Stuck? See <strong><a href="./getting-help.html">Getting Help</a></strong>.</li></ul><h2 id="integration-options" tabindex="-1">Integration options <a class="header-anchor" href="#integration-options" aria-label="Permalink to &quot;Integration options&quot;">​</a></h2><p><strong>Settings &gt; Devices &amp; services &gt; LCARdS &gt; Configure sets the sidebar entry, the log level and preview features.</strong> Changes take effect when you save, with no restart; reload the browser page to pick up a new log level.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Show sidebar panel</td><td>On</td><td>Show the LCARdS Config entry in the sidebar. Turn it off for a cleaner sidebar: the integration stays active, every card keeps working, and you can turn it back on at any time</td></tr><tr><td>Sidebar title</td><td><code>LCARdS Config</code></td><td>The sidebar entry&#39;s label</td></tr><tr><td>Sidebar icon</td><td><code>mdi:space-invaders</code></td><td>The sidebar entry&#39;s icon</td></tr><tr><td>Log level</td><td><code>warn</code></td><td>How much LCARdS logs, in the browser console and in the Home Assistant log: <code>off</code>, <code>error</code>, <code>warn</code>, <code>info</code>, <code>debug</code> or <code>trace</code>. <code>debug</code> and <code>trace</code> are very verbose: use them only for deep troubleshooting. <code>?lcards_log_level=debug</code> on a page&#39;s address overrides it for that page</td></tr><tr><td>Enable Preview Features</td><td>Off</td><td>Unlocks features still under active development. They may change; please give feedback, discuss or get help on GitHub Issues and Discussions</td></tr></tbody></table>',21)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
